package br.com.itbn.sisdent.model;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="odontogram_findings") public class OdontogramFinding extends AuditableEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="global_id",nullable=false,unique=true,updatable=false) private UUID globalId=UUID.randomUUID(); @ManyToOne(fetch=FetchType.LAZY,optional=false) private Organization organization; @ManyToOne(fetch=FetchType.LAZY,optional=false) private ClinicUnit clinicUnit; @ManyToOne(fetch=FetchType.LAZY,optional=false) private PatientOrganizationLink patientLink; @ManyToOne(fetch=FetchType.LAZY) private Practitioner practitioner; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="replacement_for_id") private OdontogramFinding replacementFor; private String toothCode; @Enumerated(EnumType.STRING) private OdontogramSurface surface; @Enumerated(EnumType.STRING) @Column(name="condition_code") private OdontogramCondition condition; private Instant observedAt; private String observationTimezone; @Column(name="clinical_note",length=500) private String clinicalNote; private Instant voidedAt; private String voidedBy; @Column(length=500) private String voidReason;
 protected OdontogramFinding(){} public OdontogramFinding(Organization o,ClinicUnit c,PatientOrganizationLink p,Practitioner r,OdontogramFinding replacement,String tooth,OdontogramSurface surface,OdontogramCondition condition,Instant at,String zone,String note){organization=o;clinicUnit=c;patientLink=p;practitioner=r;replacementFor=replacement;toothCode=tooth;this.surface=surface;this.condition=condition;observedAt=at;observationTimezone=zone;clinicalNote=note;} public Long getId(){return id;} public UUID getGlobalId(){return globalId;} public Organization getOrganization(){return organization;} public ClinicUnit getClinicUnit(){return clinicUnit;} public PatientOrganizationLink getPatientLink(){return patientLink;} public Practitioner getPractitioner(){return practitioner;} public OdontogramFinding getReplacementFor(){return replacementFor;} public String getToothCode(){return toothCode;} public OdontogramSurface getSurface(){return surface;} public OdontogramCondition getCondition(){return condition;} public Instant getObservedAt(){return observedAt;} public String getObservationTimezone(){return observationTimezone;} public String getClinicalNote(){return clinicalNote;} public Instant getVoidedAt(){return voidedAt;} public String getVoidedBy(){return voidedBy;} public String getVoidReason(){return voidReason;} public boolean isVoided(){return voidedAt!=null;} public void voidRecord(String reason,String actor){if(isVoided())throw new IllegalStateException();voidedAt=Instant.now();voidedBy=actor;voidReason=reason.strip();}
}
